def colour_existing_templates(apps, schema_editor):
    """Give existing templates a colour that matches their icon (instead of one flat default)."""
    T = apps.get_model('helpdesk', 'TicketTemplate')
    db = schema_editor.connection.alias
    for t in T.objects.using(db).all():
        c = ICON_COLORS.get(t.icon)
        if c:
            T.objects.using(db).filter(pk=t.pk).update(color=c)


